// Create creates reusable dynamic content that you can insert into Help Center articles. Provide a unique `name`, choose `inline` or `block` for `content_type`, and include at least one variation with a locale that matches `default_locale` and applies to all brands.
//
// You can create dynamic content. Requires the `read_write_dynamic_content` scope.
//
// Parameters:
//
//	name: The name of the dynamic content. Must be unique in the workspace.
//	contentType: Whether the dynamic content is a short inline value (`inline`)
//	or one or more blocks of content (`block`). Can't be changed later.
//	defaultLocale: The locale whose variation is used when there's no variation
//	for the requested locale. `variations` must include a variation for this
//	locale that applies to all brands.
//	variations: The variations of the dynamic content, one per locale and
//	optionally per brand. Set `brand_id` on a variation to override the
//	all-brands value for that brand. At least one is required.
func (sdk *DynamicContentNamespace) Create(ctx context.Context, params CreateDynamicContentParams, opts ...RequestOption) (*DynamicContent, error) {
	return CreateDynamicContent(ctx, sdk.config, params, opts...)
}

