type ConversationsNamespace struct {
	config ClientConfig
}

func NewConversationsNamespace(config ClientConfig) *ConversationsNamespace {
	return &ConversationsNamespace{
		config: config,
	}
}

// List lists conversations with cursor-based pagination. Use `per_page` to set the page size and `starting_after` to continue from a cursor; you can also request QA monitor evaluations or scorecards for each conversation.
//
// You can fetch a list of all conversations. You can optionally request the result page size and the cursor to start after to fetch the result. {% admonition type="warning" name="Pagination" %} You can use pagination to limit the number of results returned. The default is `20` results per page. See the [pagination section](https://developers.intercom.com/docs/build-an-integration/learn-more/rest-apis/pagination/#pagination-for-list-apis) for more details on how to use the `starting_after` param. {% /admonition %}
//
// Parameters:
//
//	perPage: How many results per page
//	startingAfter: String used to get the next page of conversations.
//	includeMonitors: If set to true, the response will include a
//	`monitor_evaluations` array on each conversation with any QA monitor results
//	that flagged it.
//	includeScorecards: If set to true, the response will include a `scorecards`
//	array on each conversation with any QA scorecard results.
func (sdk *ConversationsNamespace) List(ctx context.Context, params ListConversationsParams, opts ...RequestOption) (*ConversationList, error) {
	return ListConversations(ctx, sdk.config, params, opts...)
}

// Create creates a conversation initiated by a contact and returns the message created for it. Provide `from` and `body`; the message can be an in-app message, and using a visitor identifier in `from` converts that visitor to a lead contact.
//
// You can create a conversation that has been initiated by a contact (ie. user or lead). The conversation can be an in-app message only. {% admonition type="info" name="Sending for visitors" %} You can also send a message from a visitor by specifying their `user_id` or `id` value in the `from` field, along with a `type` field value of `contact`. This visitor will be automatically converted to a contact with a lead role once the conversation is created. {% /admonition %} This will return the Message model that has been created.
//
// Parameters:
//
//	from: Required object value serialized in the `from` wire field.
//	body: The content of the message. HTML is not supported.
//	subject: The title of the email. Only applicable if the message type is
//	email.
//	attachmentUrls: A list of image URLs that will be added as attachments. You
//	can include up to 10 URLs.
//	createdAt: The time the conversation was created as a UTC Unix timestamp. If
//	not provided, the current time will be used. This field is only recommneded
//	for migrating past conversations from another source into Intercom.
//	brandId: The unique identifier of the brand to associate with this
//	conversation.
func (sdk *ConversationsNamespace) Create(ctx context.Context, params CreateConversationParams, opts ...RequestOption) (*CreateConversationResponse, error) {
	return CreateConversation(ctx, sdk.config, params, opts...)
}

// Retrieve retrieves a conversation and its conversation parts. The response includes at most the 500 most recent parts; use the optional query parameters to request plaintext, translations, QA monitor evaluations, or scorecards.
//
// You can fetch the details of a single conversation. This will return a single Conversation model with all its conversation parts. {% admonition type="warning" name="Hard limit of 500 parts" %} The maximum number of conversation parts that can be returned via the API is 500. If you have more than that we will return the 500 most recent conversation parts. {% /admonition %} For AI agent conversation metadata, please note that you need to have the agent enabled in your workspace, which is a [paid feature](https://www.intercom.com/help/en/articles/8205718-fin-resolutions#h_97f8c2e671).
//
// Parameters:
//
//	conversationId: The id of the conversation to target
//	displayAs: Set to plaintext to retrieve conversation messages in plain text.
//	This affects both the body and subject fields. Inline links are rendered as
//	`label (url)`, preserving the link URL alongside the visible text.
//	includeTranslations: If set to true, conversation parts will be translated
//	to the detected language of the conversation.
//	includeMonitors: If set to true, the response will include a
//	`monitor_evaluations` array with any QA monitor results that flagged this
//	conversation.
//	includeScorecards: If set to true, the response will include a `scorecards`
//	array with any QA scorecard results for this conversation.
func (sdk *ConversationsNamespace) Retrieve(ctx context.Context, params RetrieveConversationParams, opts ...RequestOption) (*Conversation, error) {
	return RetrieveConversation(ctx, sdk.config, params, opts...)
}

// Update updates an existing conversation, including its title, read state, company association, and writable custom attributes. Supply only the fields you want to change; set `company_id` to null to remove the company association. Use the reply or manage conversation endpoints to send messages or change assignment and conversation state.
//
// You can update an existing conversation. {% admonition type="info" name="Replying and other actions" %} If you want to reply to a coveration or take an action such as assign, unassign, open, close or snooze, take a look at the reply and manage endpoints. {% /admonition %} {% admonition type="info" %} This endpoint handles both **conversation updates** and **custom object associations**. See _`update a conversation with an association to a custom object instance`_ in the request/response examples to see the custom object association format. {% /admonition %} {% admonition type="danger" name="Breaking change: duplicate custom attribute names" %} The `PUT /conversations/{id}` endpoint now returns a `400 INVALID_PARAMETER` error when the request includes `custom_attributes` and your workspace contains multiple non-archived conversation custom attributes with the same name. Previously, the update would silently apply to a non-deterministic attribute. To resolve, rename or archive the duplicate attribute in your workspace settings, then retry the request. {% /admonition %}
//
// Parameters:
//
//	conversationId: The id of the conversation to target
//	displayAs: Set to plaintext to retrieve conversation messages in plain text.
//	This affects both the body and subject fields. Inline links are rendered as
//	`label (url)`, preserving the link URL alongside the visible text.
//	read: Mark a conversation as read within Intercom.
//	title: The title given to the conversation
//	customAttributes: The custom attributes which are set on this object, as
//	key-value pairs. For relationship attributes the value should be a list of
//	custom object instance models. Only attributes a caller may set are accepted
//	here — attributes Intercom generates are returned in responses only.
//	companyId: The ID of the company that the conversation is associated with.
//	The unique identifier for the company which is given by Intercom. Set to nil
//	to remove company.
func (sdk *ConversationsNamespace) Update(ctx context.Context, params UpdateConversationParams, opts ...RequestOption) (*Conversation, error) {
	return UpdateConversation(ctx, sdk.config, params, opts...)
}

// Delete deletes a conversation permanently, with reporting-data retention controlled by `retain_metrics`. When `retain_metrics` is `false`, the authenticated user must have the `delete_conversations_and_metrics` OAuth scope; this also deletes the conversation's associated reporting data.
//
// {% admonition type="warning" name="Irreversible operation" %} Deleting a conversation is permanent and cannot be reversed. {% /admonition %} You can delete a single conversation. The behavior depends on the `retain_metrics` parameter: - **With `retain_metrics=true` (default)**: Deletes the conversation while retaining reporting data. The conversation will still appear in reporting, though some data may be incomplete due to the deletion. - **With `retain_metrics=false`**: Deletes the conversation and all associated reporting data. The conversation will be completely removed from both the inbox and all reporting. {% admonition type="info" name="Required scope for retain_metrics=false" %} Using `retain_metrics=false` requires the `delete_conversations_and_metrics` OAuth scope. {% /admonition %} For more info, see [this help center article](https://www.intercom.com/help/en/articles/13885146-deleting-a-conversation).
//
// Parameters:
//
//	conversationId: id
//	retainMetrics: If true (default), deletes the conversation while retaining
//	reporting data. If false, deletes the conversation and all associated
//	reporting data. Setting to false requires the
//	`delete_conversations_and_metrics` OAuth scope.
func (sdk *ConversationsNamespace) Delete(ctx context.Context, params DeleteConversationParams, opts ...RequestOption) (*ConversationDeleted, error) {
	return DeleteConversation(ctx, sdk.config, params, opts...)
}

// Search searches conversations using filters on searchable conversation attributes. Provide a `query` with a filter or a group of filters, and use `pagination` to control the result page. You can combine filters with AND and OR operators, nest up to two filter levels, and include up to 15 filters in each group.
//
// You can search for multiple conversations by the value of their attributes in order to fetch exactly which ones you want. To search for conversations, you need to send a `POST` request to `https://api.intercom.io/conversations/search`. This will accept a query object in the body which will define your filters in order to search for conversations. {% admonition type="warning" name="Optimizing search queries" %} Search queries can be complex, so optimizing them can help the performance of your search. Use the `AND` and `OR` operators to combine multiple filters to get the exact results you need and utilize pagination to limit the number of results returned. The default is `20` results per page and maximum is `150`. See the [pagination section](https://developers.intercom.com/docs/build-an-integration/learn-more/rest-apis/pagination/#example-search-conversations-request) for more details on how to use the `starting_after` param. {% /admonition %} ### Nesting & Limitations You can nest these filters in order to get even more granular insights that pinpoint exactly what you need. Example: (1 OR 2) AND (3 OR 4). There are some limitations to the amount of multiple's there can be: - There's a limit of max 2 nested filters - There's a limit of max 15 filters for each AND or OR group ### Accepted Fields Most keys listed in the conversation model are searchable, whether writeable or not. The value you search for has to match the accepted type, otherwise the query will fail (ie. as `created_at` accepts a date, the `value` cannot be a string such as `"foorbar"`). The `source.body` field is unique as the search will not be performed against the entire value, but instead against every element of the value separately. For example, when searching for a conversation with a `"I need support"` body - the query should contain a `=` operator with the value `"support"` for such conversation to be returned. A query with a `=` operator and a `"need support"` value will not yield a result.…
//
// Parameters:
//
//	query: Required API value serialized in the `query` wire field.
//	includeMonitors: If set to true, the response will include a
//	`monitor_evaluations` array on each conversation with any QA monitor results
//	that flagged it.
//	includeScorecards: If set to true, the response will include a `scorecards`
//	array on each conversation with any QA scorecard results.
//	pagination: Optional object value serialized in the `pagination` wire field.
func (sdk *ConversationsNamespace) Search(ctx context.Context, params SearchConversationsParams, opts ...RequestOption) (*ConversationList, error) {
	return SearchConversations(ctx, sdk.config, params, opts...)
}

// Reply submits a reply to a conversation as an admin or on behalf of a contact, or adds an admin note. Choose a contact identifier or provide the admin reply fields, including `message_type` and `admin_id` for an admin reply. Bot replies to inbound email conversations are not sent to customers by default; contact your accounts team to enable the email-reply feature.
//
// You can reply to a conversation with a message from an admin or on behalf of a contact, or with a note for admins. {% admonition type="warning" name="Bot replies to inbound email" %} By default, bot or Operator replies to an inbound email conversation aren't sent to your customer. The reply is stored as an unnotifiable bot comment, and no `seen` receipt is generated until an email is actually delivered. To send these replies as outbound emails, reach out to your accounts team to enable the email-reply feature flag for your workspace. {% /admonition %} {% admonition type="info" name="Managing a conversation" %} To close, open, snooze or assign a conversation, use Manage a conversation. {% /admonition %}
//
// Parameters:
//
//	conversationId: The Intercom provisioned identifier for the conversation or
//	the string "last" to reply to the last part of the conversation
func (sdk *ConversationsNamespace) Reply(ctx context.Context, params ReplyConversationParams, opts ...RequestOption) (*Conversation, error) {
	return ReplyConversation(ctx, sdk.config, params, opts...)
}
